const EMP = { TAM: { s: 41.36, p: 648.81, a: 1190239 }, GLO: { s: 31.80, p: 588.95, a: 915169 }, AZU: { s: 26.83, p: 706.32, a: 772036 } }, MKT = 645.22;
const FX = n => Math.round(n).toLocaleString('pt-BR'), RS = n => 'R$ ' + n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }), R0 = n => 'R$ ' + Math.round(n).toLocaleString('pt-BR');
const BL = ['até 300', '300–600', '600–1.000', '1.000–2.000', '> 2.000'], HL = D.TODAS.hist.map((_, i) => i * 100 + (i == D.TODAS.hist.length - 1 ? '+' : ''));
let sel = 'TODAS', ch = {}; const $ = id => document.getElementById(id), css = () => getComputedStyle(document.documentElement);
function mk(id, type, data, opt = {}) {
    const s = css(), g = s.getPropertyValue('--grid'), m = s.getPropertyValue('--mut'), ink = s.getPropertyValue('--ink');
    if (ch[id]) ch[id].destroy(); const h = !!opt.h;
    ch[id] = new Chart($(id), {
        type, data, options: {
            responsive: true, maintainAspectRatio: false, indexAxis: h ? 'y' : 'x', animation: false, layout: { padding: { right: h ? (opt.pad || 58) : 0 } },
            plugins: { legend: { display: false }, tooltip: { enabled: !opt.fmt }, datalabels: opt.fmt ? { display: true, anchor: 'end', align: 'end', color: ink, font: { weight: '600', size: 12 }, formatter: opt.fmt } : { display: false } },
            scales: { x: { grid: { color: g }, ticks: { color: m }, display: !opt.fmt || !h }, y: { grid: { color: h ? 'transparent' : g }, ticks: { color: ink, font: { size: h ? 12 : 11 } } } }
        }
    })
}
function render() {
    const d = D[sel], s = css(), V = n => s.getPropertyValue(n).trim(), c1 = V('--c1'), c3 = V('--c3'), c2 = V('--c2'), gray = '#8a8886';
    $('k1').textContent = FX(d.ass); $('k2').textContent = 'R$ ' + FX(d.rec / 1e6) + ' mi'; $('k3').textContent = RS(d.pond); $('k4').textContent = RS(d.med);
    mk('c1', 'bar', { labels: HL, datasets: [{ data: d.hist, backgroundColor: c1, barPercentage: 1, categoryPercentage: .95 }] });
    mk('c2', 'bar', { labels: BL, datasets: [{ data: d.bands, backgroundColor: c2 }] });
    const E = Object.keys(EMP).sort((a, b) => EMP[b].s - EMP[a].s), on = e => sel == 'TODAS' || sel == e;
    const pc = (v, n = 1) => v.toLocaleString('pt-BR', { maximumFractionDigits: n });
    mk('c3', 'bar', { labels: E, datasets: [{ data: E.map(e => EMP[e].s), backgroundColor: E.map(e => on(e) ? c1 : gray), barThickness: 34 }] }, { h: 1, fmt: v => pc(v) + '% dos assentos' + '', pad: 110 });
    $('n3').innerHTML = '<b>' + E[0] + '</b> lidera com ' + pc(EMP[E[0]].s) + '% de todos os assentos vendidos; as três companhias somam praticamente 100% do mercado.' + (sel != 'TODAS' ? ' Destaque: <b>' + sel + '</b> (' + pc(EMP[sel].s) + '%).' : '');
    const F = Object.keys(EMP).sort((a, b) => EMP[b].p - EMP[a].p), hi = F[0], lo = F[F.length - 1];
    mk('c4', 'bar', { labels: F, datasets: [{ data: F.map(e => EMP[e].p), backgroundColor: F.map(e => !on(e) ? gray : EMP[e].p > MKT ? c3 : c1), barThickness: 34 }] }, { h: 1, fmt: v => R0(v) + '  (' + (v >= MKT ? '+' : '') + pc((v / MKT - 1) * 100, 0) + '%)', pad: 100 });
    $('n4').innerHTML = 'Laranja: acima da média do mercado (<b>R$ 645</b>). Azul: abaixo. Em média, <b>' + hi + '</b> cobra R$ ' + Math.round(EMP[hi].p - EMP[lo].p) + ' a mais por assento que <b>' + lo + '</b> (+' + pc((EMP[hi].p / EMP[lo].p - 1) * 100, 0) + '%).';
    const G = Object.keys(EMP).sort((a, b) => EMP[b].a - EMP[a].a);
    mk('c5', 'bar', { labels: G, datasets: [{ data: G.map(e => EMP[e].a), backgroundColor: G.map(e => on(e) ? c2 : gray), barThickness: 34 }] }, { h: 1, fmt: v => FX(v), pad: 80 });
    $('n5').innerHTML = '<b>' + G[0] + '</b> vendeu ' + FX(EMP[G[0]].a) + ' passagens, ' + FX(EMP[G[0]].a - EMP[G[1]].a) + ' a mais que <b>' + G[1] + '</b> (+' + pc((EMP[G[0]].a / EMP[G[1]].a - 1) * 100, 0) + '%). Os dados são só de janeiro; para ver o total do ano, seria preciso incluir os outros meses.';
    $('n2').innerHTML = '<b>' + pc(d.bands[0] + d.bands[1], 0) + '%</b> dos assentos custam até R$ 600; só <b>' + pc(d.bands[4], 1) + '%</b> custam mais de R$ 2.000.';
    drawMap()
}
