const nm = c => { const v = M.info[c]; return v ? (nmc[v[0]] > 1 && v[1] ? v[0] + ' (' + v[1] + ')' : v[0]) : c };
const STOPS = ['#ffe9a8', '#fdbf6f', '#f7873f', '#e24a33', '#a50f15'];
const hex = h => [1, 3, 5].map(i => parseInt(h.substr(i, 2), 16));
function col(t) { t = Math.max(0, Math.min(1, t)) * (STOPS.length - 1); const i = Math.min(STOPS.length - 2, Math.floor(t)), f = t - i, a = hex(STOPS[i]), b = hex(STOPS[i + 1]); return 'rgb(' + a.map((x, k) => Math.round(x + (b[k] - x) * f)).join(',') + ')' }
const ref = Object.values(M.S.TODAS.ap).filter(v => v[0] >= 1000).map(v => v[1]).sort((a, b) => a - b), LO = ref[Math.floor(ref.length * .05)], HI = ref[Math.floor(ref.length * .95)];
